:root{--ink:#091111;--panel:#101b1a;--panel-2:#13211f;--line:#263532;--muted:#75817b;--cream:#e6e9d8;--acid:#d5fa54;--orange:#f77a50;--cyan:#71d7c6;--mono:'Chakra',sans-serif;--body:'Rajdhani',sans-serif}
*{box-sizing:border-box}html{background:var(--ink);scroll-behavior:smooth}body{margin:0;color:var(--cream);font:500 16px/1.35 var(--body);min-height:100vh;background:radial-gradient(ellipse at 42% 0%,#15211d 0,transparent 58%),var(--ink)}button,a{-webkit-tap-highlight-color:transparent}.app-shell{max-width:1390px;margin:0 auto;padding:0 40px}.topbar{height:74px;border-bottom:1px solid #25312e;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;color:var(--cream);text-decoration:none}.brand-mark{width:24px;height:24px;display:grid;grid-template-columns:repeat(2,1fr);gap:3px;transform:rotate(-9deg)}.brand-mark span{background:var(--acid)}.brand-mark span:nth-child(2){opacity:.7}.brand-mark span:nth-child(3){opacity:.48}.brand-mark span:nth-child(4){opacity:.8}.brand-name{font:700 15px var(--mono);letter-spacing:.07em}.brand-name span{color:var(--acid);margin-left:5px}.season-tag{color:#9ba69e;font:600 11px var(--mono);letter-spacing:.08em}.season-tag i{color:#59645c;font-style:normal;padding:0 8px}.live-dot,.frame-live i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 11px #d5fa5480;margin-right:8px}.top-right{display:flex;align-items:center;gap:11px}.profile-label{color:#a7afa4;font:600 10px var(--mono);letter-spacing:.06em}.avatar{height:30px;width:30px;border:1px solid #526052;display:grid;place-items:center;color:var(--acid);font:700 13px var(--mono);background:#18231e}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 294px;gap:27px;padding:27px 0 18px}.intro-heading{margin:0 0 17px}.eyebrow{font:600 10px var(--mono);letter-spacing:.14em;color:#9eaaa0;display:flex;align-items:center;gap:9px}.eyebrow-line{height:1px;width:20px;background:var(--acid)}h1{font:700 clamp(29px,3.2vw,43px)/1.12 var(--mono);letter-spacing:-.055em;margin:8px 0 4px;color:#eff0df}h1 em{font-style:normal;color:var(--acid)}.title-colon{color:var(--orange)}.intro-heading p{margin:0;color:#9ca69b;font-size:16px}.intro-heading p b{color:#dfe3d3;font-weight:600}.game-frame{border:1px solid #3a4840;background:#0c1412;box-shadow:0 20px 55px #0005}.frame-topline,.frame-footer{height:34px;padding:0 13px;display:flex;align-items:center;justify-content:space-between;font:600 9px var(--mono);letter-spacing:.075em;color:#a0aaa0}.frame-topline{border-bottom:1px solid #27322e;background:#111b18}.signal-icon{color:var(--acid);font-size:13px;margin-right:7px}.frame-live{color:#b4c1b2}.frame-live i{width:6px;height:6px;margin-right:5px}.canvas-wrap{position:relative;overflow:hidden;background:#101b17;aspect-ratio:1.75}.canvas-wrap canvas{display:block;width:100%;height:100%;touch-action:none}.frame-footer{height:31px;border-top:1px solid #27322e;color:#758078;font-size:8px}.frame-footer b{color:#a3afa3;font-weight:600}.footer-dot{width:5px;height:5px;display:inline-block;background:var(--orange);border-radius:100%;margin-right:6px}.footer-divider{color:#59645c;padding:0 4px;font-style:normal}
.start-overlay,.end-overlay{position:absolute;inset:0;display:flex;align-items:center;background:linear-gradient(90deg,rgba(8,15,13,.95) 0%,rgba(8,15,13,.85) 40%,rgba(8,15,13,.15) 100%),linear-gradient(0deg,#07100e8c,transparent 55%);overflow:hidden}.start-overlay:before{content:"";position:absolute;right:5%;top:9%;width:41%;height:82%;border:1px solid #c0e79a12;clip-path:polygon(9% 0,100% 0,100% 100%,0 100%,0 14%);background:repeating-linear-gradient(0deg,transparent 0 38px,#c1dba90a 39px 40px),repeating-linear-gradient(90deg,transparent 0 38px,#c1dba90a 39px 40px)}.overlay-grain{position:absolute;inset:0;pointer-events:none;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.3'/%3E%3C/svg%3E")}.start-content{position:relative;z-index:1;margin-left:7%;width:350px}.mission-stamp{display:flex;gap:0;align-items:center;font:600 9px var(--mono);letter-spacing:.09em;margin-bottom:16px}.mission-stamp span{background:var(--acid);color:#152018;padding:6px 9px}.mission-stamp strong{border:1px solid #899184;color:#dfe3d2;padding:5px 9px;font-weight:600}.start-title{font:700 clamp(30px,4vw,47px)/.95 var(--mono);letter-spacing:-.06em;color:#f2f1e2}.start-title span{color:var(--acid)}.start-content p{color:#afb6a7;font-size:15px;line-height:1.38;margin:11px 0 17px}.primary-button{border:0;background:var(--acid);color:#162016;min-width:195px;height:41px;padding:0 13px 0 16px;display:flex;align-items:center;justify-content:space-between;gap:30px;cursor:pointer;font:700 11px var(--mono);letter-spacing:.055em;transition:background .2s,transform .2s}.primary-button:hover{background:#e2ff83;transform:translateY(-2px)}.primary-button b{font-size:18px;font-weight:600}.start-foot{margin-top:20px;display:flex;gap:18px;color:#94a094;font:600 8px var(--mono);letter-spacing:.04em}.start-foot span:first-child{color:#d1dcbd}.overlay-coordinates{position:absolute;right:14px;bottom:13px;color:#9ba59a;font:500 8px var(--mono);letter-spacing:.05em}.end-overlay{z-index:5;justify-content:center;background:#08110fe8;backdrop-filter:blur(4px)}.end-overlay.hidden{display:none}.end-card{text-align:center;width:min(380px,90%)}.end-kicker{font:600 9px var(--mono);letter-spacing:.16em;color:var(--acid)}.end-card h2{font:700 28px var(--mono);margin:7px 0;color:#eff0df}.end-card p{color:#aeb8a9;margin:0 auto 15px;max-width:290px}.end-stats{display:flex;justify-content:center;gap:23px;margin:12px 0 17px}.end-stat b{display:block;color:var(--acid);font:700 19px var(--mono)}.end-stat span{display:block;color:#9aa59a;font:600 8px var(--mono);letter-spacing:.08em}.end-card .primary-button{margin:auto}
.controls-row{display:flex;align-items:center;gap:14px;padding:12px 2px;color:#a7afa2;min-height:48px}.control-tip{display:flex;align-items:center;gap:4px;white-space:nowrap}.control-tip kbd{font:600 9px var(--mono);color:#bdc4b8;border:1px solid #47524a;background:#17211d;min-width:18px;height:20px;padding:2px 4px;text-align:center;border-radius:2px}.control-tip span{font:600 8px var(--mono);letter-spacing:.04em;margin-left:4px}.sound-button{margin-left:auto;border:0;background:none;color:#89968a;cursor:pointer;font:600 9px var(--mono);letter-spacing:.05em}.sound-button span{font-size:14px;color:var(--acid);padding-right:4px}.sound-button b{color:#c3ccb8;font-weight:600;margin-left:5px}.mobile-tip{display:none}
.intel-column{display:flex;flex-direction:column;gap:12px;padding-top:1px}.panel{background:linear-gradient(145deg,#14201d,#101917);border:1px solid #2b3934;padding:14px 15px;position:relative}.panel-heading{display:flex;justify-content:space-between;align-items:center;font:600 9px var(--mono);letter-spacing:.1em;color:#a4b0a3;border-bottom:1px solid #2b3934;padding-bottom:10px}.refresh-mark{font-size:16px;color:#7a8a78}.daily-date{display:flex;align-items:center;justify-content:space-between;color:#91a091;font:600 8px var(--mono);letter-spacing:.07em;margin-top:12px}.daily-badge{border:1px solid #627845;color:var(--acid);padding:3px 5px;font-size:7px}.daily-panel h2{font:700 21px/.99 var(--mono);letter-spacing:-.035em;margin:12px 0 9px;color:#e8ebd9}.daily-panel h2 span{color:var(--acid)}.daily-panel>p{color:#9ba79c;font-size:14px;line-height:1.3;margin:0 0 13px}.brief-goals{border-top:1px solid #2a3832;padding-top:7px}.brief-goals>div{height:25px;display:grid;grid-template-columns:20px 1fr auto;align-items:center;font-size:13px;color:#b1bbad}.goal-icon{font-size:14px;color:var(--acid)}.brief-goals b{font:600 10px var(--mono);color:#d8e2c7}.progress-panel{padding-bottom:12px}.record-icon{color:var(--acid);font-size:12px}.record-main{display:flex;justify-content:space-between;align-items:center;padding:11px 0 9px}.record-main>div{display:flex;flex-direction:column}.record-label,.record-rank>span{font:600 8px var(--mono);color:#8e9b90;letter-spacing:.08em}.record-main strong{font:700 23px var(--mono);color:#e8ead9;line-height:1.1;margin-top:3px}.record-rank{text-align:right}.record-rank strong{color:var(--acid);font-size:18px}.record-rank small{font:600 8px var(--mono);color:#9aa793}.record-track{height:3px;background:#344039}.record-track span{height:100%;width:0;display:block;background:var(--acid);transition:width .5s}.record-caption{display:flex;justify-content:space-between;gap:6px;margin-top:7px;color:#89958a;font:600 7px var(--mono);letter-spacing:.045em}.field-panel{padding-bottom:8px}.field-mark{color:var(--acid)}.field-note{display:grid;grid-template-columns:24px 1fr;gap:7px;margin-top:9px}.note-index{font:600 9px var(--mono);color:var(--acid);padding-top:2px}.field-note p{font-size:12px;color:#9eaa9d;line-height:1.23;margin:0}.field-note b{font-weight:600;color:#d0d8c8}.footer-quote{margin-top:auto;color:#8e9c8c;font:600 10px var(--mono);letter-spacing:.07em;padding:13px 2px 0}.footer-quote span{color:var(--acid);font:700 24px Georgia;vertical-align:-5px;padding-right:4px}.site-footer{border-top:1px solid #25312e;display:flex;justify-content:space-between;padding:14px 0 18px;color:#6b786f;font:600 8px var(--mono);letter-spacing:.06em}.site-footer i{font-style:normal;color:var(--acid)}
.toast{position:absolute;z-index:4;left:50%;top:14px;transform:translate(-50%,-10px);opacity:0;pointer-events:none;background:#d5fa54;color:#152019;padding:7px 13px;font:700 10px var(--mono);letter-spacing:.04em;transition:all .22s}.toast.show{transform:translate(-50%,0);opacity:1}.mobile-controls{display:none}
@media(max-width:1050px){.app-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 260px;gap:18px}.controls-row{gap:8px}.control-tip span{font-size:7px;margin-left:2px}.control-tip kbd{font-size:8px}.panel{padding-left:12px;padding-right:12px}}
@media(max-width:800px){.app-shell{padding:0 18px}.game-layout{grid-template-columns:1fr;gap:18px;padding-top:21px}.intel-column{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field-panel{grid-column:span 2}.footer-quote{display:none}.site-footer{margin-top:4px}.intro-heading{margin-bottom:13px}.game-layout .play-column{min-width:0}.frame-topline{height:30px}.canvas-wrap{aspect-ratio:1.58}.start-content{margin-left:6%}.start-title{font-size:clamp(30px,6vw,45px)}.start-content p{font-size:13px}.controls-row{flex-wrap:wrap}.sound-button{margin-left:auto}.field-note{margin-top:8px}.field-panel{display:grid;grid-template-columns:1fr 1fr;column-gap:13px}.field-panel .panel-heading{grid-column:span 2}.field-note:last-child{grid-column:span 2}.daily-panel h2{font-size:19px}}
@media(max-width:520px){.app-shell{padding:0 12px}.topbar{height:58px}.season-tag{font-size:8px;letter-spacing:.04em}.season-tag i{padding:0 3px}.brand{gap:8px}.brand-mark{width:19px;height:19px}.brand-name{font-size:12px}.profile-label{font-size:8px}.avatar{width:26px;height:26px}.game-layout{padding-top:16px}.eyebrow{font-size:8px}h1{font-size:clamp(24px,7vw,34px);letter-spacing:-.07em}.intro-heading p{font-size:14px}.canvas-wrap{aspect-ratio:1.22}.start-overlay{background:linear-gradient(90deg,rgba(8,15,13,.96),rgba(8,15,13,.70) 67%,rgba(8,15,13,.15)),linear-gradient(0deg,#07100e8c,transparent 55%)}.start-overlay:before{right:-2%;width:40%;height:75%;top:12%}.start-content{width:74%;margin-left:6%;}.mission-stamp{margin-bottom:10px}.start-title{font-size:clamp(28px,8.5vw,39px)}.start-content p{font-size:12px;margin:8px 0 12px}.primary-button{height:38px;min-width:172px;font-size:10px}.start-foot{margin-top:13px;gap:10px;font-size:7px}.overlay-coordinates{font-size:6px;right:7px;bottom:7px}.frame-footer{height:27px;font-size:7px;padding:0 8px}.frame-topline{font-size:8px;padding:0 9px}.controls-row{gap:6px;padding:9px 0}.control-tip{display:none}.mobile-tip{display:block;color:#9ba697;font:600 8px var(--mono);letter-spacing:.045em}.sound-button{font-size:8px}.intel-column{gap:8px}.panel{padding:11px 10px}.panel-heading{font-size:8px;padding-bottom:7px}.daily-date{font-size:7px;margin-top:9px}.daily-panel h2{font-size:17px;margin:9px 0 6px}.daily-panel>p{font-size:12px;margin-bottom:8px}.brief-goals>div{height:22px;font-size:12px}.goal-icon{font-size:12px}.record-main{padding:9px 0 7px}.record-main strong{font-size:19px}.record-rank strong{font-size:16px}.record-caption{font-size:6px}.field-panel{padding-bottom:9px}.field-note p{font-size:11px}.site-footer{font-size:7px;padding:11px 0 14px}.site-footer span:nth-child(2){display:none}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none;z-index:3}.joystick,.touch-action,.touch-dash{pointer-events:auto;position:absolute;bottom:13px;width:62px;height:62px;border:1px solid #d5fa5480;background:#17241fcc;border-radius:50%;touch-action:none;color:var(--acid);display:grid;place-items:center}.joystick{left:13px}.joy-knob{width:27px;height:27px;border-radius:50%;background:#d5fa54a3;border:1px solid #e6ffbd}.touch-action{right:13px;font:700 14px var(--mono)}.touch-dash{right:82px;width:48px;height:48px;bottom:20px;font:700 19px var(--mono);background:#f77a5080;border-color:#ff9b7a}
}
@media(max-width:370px){.season-tag{display:none}.start-foot span:last-child{display:none}.daily-panel h2{font-size:15px}.field-note p{font-size:10px}.intel-column{grid-template-columns:1fr 1fr}.canvas-wrap{aspect-ratio:1.08}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { start: $('startOverlay'), end: $('endOverlay'), startButton: $('startButton'), retry: $('retryButton'), toast: $('toast'), status: $('statusText'), sound: $('soundButton'), soundState: $('soundState'), soundIcon: $('soundIcon') };
  const DAY = new Date();
  const dateKey = `${DAY.getFullYear()}-${String(DAY.getMonth()+1).padStart(2,'0')}-${String(DAY.getDate()).padStart(2,'0')}`;
  const dateLabel = DAY.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: '2-digit' }).toUpperCase();
  const shortDate = DAY.toLocaleDateString('en-US', { month: 'short', day: '2-digit' }).toUpperCase();
  $('dateStamp').textContent = shortDate;
  $('fullDate').textContent = dateLabel;
  const stored = readRecord();
  renderRecord();
  const W = 1200, H = 760, DURATION = 120;
  let state = 'menu', lastFrame = 0, elapsed = 0, remaining = DURATION, lives = 3, rescued = 0, tags = 0;
  let player, hunters = [], friends = [], grass = [], buildings = [], trees = [], decor = [], rescueTarget = null;
  let toastTimer = 0, hitFlash = 0, soundOn = false, audioCtx = null;
  const keys = new Set(), touch = { x: 0, y: 0, action: false, dash: false };
  let seed = 0;
  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
  const dist = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
  function readRecord(){ try { return JSON.parse(localStorage.getItem('zero-hour-record') || '{}'); } catch { return {}; } }
  function renderRecord(){
    const r = readRecord();
    $('bestTime').textContent = r.best ? '02:00' : '--:--';
    $('streakCount').textContent = String(r.streak || 0);
    $('rescuedLifetime').textContent = `${r.rescues || 0} FRIEND${r.rescues === 1 ? '' : 'S'} RESCUED`;
    $('recordHint').textContent = r.best ? 'BEST RUN · FULL EXTRACTION' : 'YOUR FIRST RUN AWAITS';
    $('bestBar').style.width = r.best ? '100%' : '0%';
  }
  function random(){ seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
  function hashDate(){ let n=2166136261; for(const c of dateKey) n=Math.imul(n^c.charCodeAt(0),16777619); return n>>>0; }
  function resize(){
    const rect=canvas.getBoundingClientRect(), dpr=Math.min(devicePixelRatio||1,2);
    if(!rect.width||!rect.height)return;
    const w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
  }
  new ResizeObserver(resize).observe(canvas);
  function setupRun(){
    seed=hashDate(); elapsed=0;remaining=DURATION;lives=3;rescued=0;tags=0;hitFlash=0;rescueTarget=null;
    player={x:125,y:385,r:15,speed:162,stamina:100,dash:0,dashCd:0,freeze:0,invuln:0,dir:0,hidden:false,steps:0};
    friends=[{x:940,y:135,label:'MICA',rescued:false,captured:false,color:'#f7a963'}, {x:1015,y:540,label:'JUNE',rescued:false,captured:false,color:'#75d9c7'}, {x:575,y:642,label:'SOL',rescued:false,captured:false,color:'#c49aff'}];
    hunters=[{x:790,y:190,r:18,speed:82,dir:0,alert:0,target:null,tagCd:0,phase:random()*8,color:'#ef6a4e'}, {x:840,y:558,r:18,speed:77,dir:0,alert:0,target:null,tagCd:0,phase:random()*8,color:'#f18b58'}, {x:410,y:170,r:17,speed:74,dir:0,alert:0,target:null,tagCd:0,phase:random()*8,color:'#df6754'}];
    buildWorld(); state='playing';ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.status.textContent='OPERATION IN PROGRESS';say('FIND YOUR CREW. STAY OUT OF SIGHT.');
  }
  function buildWorld(){
    buildings=[];trees=[];grass=[];decor=[];
    const blocks=[
      [215,90,160,103],[465,87,176,112],[908,73,170,123],
      [64,253,165,128],[314,267,176,120],[586,262,175,119],[893,286,211,113],
      [192,502,190,108],[432,498,175,117],[728,490,165,117],[1001,470,140,111]
    ];
    for(let i=0;i<blocks.length;i++){const [x,y,w,h]=blocks[i];buildings.push({x,y,w,h,id:i,light:random()});}
    grass=[{x:287,y:205,r:48},{x:746,y:212,r:44},{x:432,y:397,r:57},{x:835,y:405,r:47},{x:490,y:670,r:46},{x:1120,y:225,r:39},{x:81,y:655,r:48}];
    for(let i=0;i<73;i++){
      const x=35+random()*1130,y=37+random()*686;
      if(buildings.some(b=>x>b.x-18&&x<b.x+b.w+18&&y>b.y-15&&y<b.y+b.h+15))continue;
      trees.push({x,y,r:7+random()*9,shade:random(),type:random()>.18?'tree':'bush'});
    }
    for(let i=0;i<190;i++) decor.push({x:random()*W,y:random()*H,a:random(),t:random()});
  }
  function startRun(){ if(soundOn)beep(420,.06); setupRun(); }
  ui.startButton.addEventListener('click',startRun);ui.retry.addEventListener('click',startRun);
  function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.1;}
  function keyName(e){return e.key.toLowerCase();}
  addEventListener('keydown',e=>{const k=keyName(e);if(['arrowup','arrowdown','arrowleft','arrowright',' ','shift'].includes(k))e.preventDefault();keys.add(k);if(k===' '&&!e.repeat)dash();if(k==='enter'&&state!=='playing')startRun();});
  addEventListener('keyup',e=>keys.delete(keyName(e)));
  $('touchAction').addEventListener('pointerdown',e=>{e.preventDefault();touch.action=true;$('touchAction').setPointerCapture(e.pointerId);});
  $('touchAction').addEventListener('pointerup',()=>touch.action=false);$('touchAction').addEventListener('pointercancel',()=>touch.action=false);
  $('touchDash').addEventListener('pointerdown',e=>{e.preventDefault();dash();});
  const joy=$('joystick'),knob=$('joyKnob');let joyPointer=null;
  joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);moveJoy(e);});
  joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e);});
  joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);
  function moveJoy(e){const r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.max(1,Math.hypot(dx,dy)),n=Math.min(m,23);touch.x=dx/m*n/23;touch.y=dy/m*n/23;knob.style.transform=`translate(${touch.x*22}px,${touch.y*22}px)`;}
  function endJoy(){joyPointer=null;touch.x=0;touch.y=0;knob.style.transform='';}
  function dash(){if(state!=='playing'||player.dashCd>0||player.stamina<17)return;player.dash=.19;player.dashCd=1.15;player.stamina=Math.max(0,player.stamina-17);if(soundOn)beep(260,.07);}
  $('soundButton').addEventListener('click',()=>{soundOn=!soundOn;ui.soundState.textContent=soundOn?'ON':'OFF';ui.soundIcon.textContent=soundOn?'♫':'♩';if(soundOn){audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();beep(510,.08);}});

